import { describe, expect, spyOn, test } from "bun:test";
import { readFileSync } from "node:fs";
import * as XLSX from "@e965/xlsx";
import { extractText as unpdfExtractText } from "unpdf";
import { extractText } from "../../../src/files/extract.ts";
import { log } from "../../../src/observability/log.ts";
import {
  DOCX_MIME,
  docxWithParagraphs,
  pdfWithPages,
  XLSX_MIME,
  xlsxWithRows,
} from "../../helpers/document-fixtures.ts";

// Committed at test/fixtures/files/spreadsheet-sample.xlsx and regenerated by
// the .py generator beside it, which documents the grid. Every column pins a
// case: `Note` holds the CSV delimiter, embedded quotes, a newline, non-ASCII
// and a padded string; `Opened` / `Checked` / `Shift` are date-only, datetime
// and time-only cells; `Ratio` holds a percent and a formula-error cell.
const spreadsheetFixture = () =>
  readFileSync(new URL("../../fixtures/files/spreadsheet-sample.xlsx", import.meta.url));

describe("extractText", () => {
  test("text/plain returns file content", async () => {
    const buf = Buffer.from("hello world");
    const result = await extractText(buf, "text/plain");
    expect(result).toEqual({ text: "hello world", truncated: false });
  });

  test("text/csv returns CSV content", async () => {
    const csv = "name,age\nAlice,30\nBob,25";
    const result = await extractText(Buffer.from(csv), "text/csv");
    expect(result).toEqual({ text: csv, truncated: false });
  });

  test("application/json returns JSON string", async () => {
    const json = '{"key":"value"}';
    const result = await extractText(Buffer.from(json), "application/json");
    expect(result).toEqual({ text: json, truncated: false });
  });

  test("text/markdown returns markdown content", async () => {
    const md = "# Hello\n\nWorld";
    const result = await extractText(Buffer.from(md), "text/markdown");
    expect(result).toEqual({ text: md, truncated: false });
  });

  test("text/html returns HTML content", async () => {
    const html = "<h1>Hello</h1>";
    const result = await extractText(Buffer.from(html), "text/html");
    expect(result).toEqual({ text: html, truncated: false });
  });

  test("application/xml returns XML content", async () => {
    const xml = "<root><item>test</item></root>";
    const result = await extractText(Buffer.from(xml), "application/xml");
    expect(result).toEqual({ text: xml, truncated: false });
  });

  test("application/yaml returns YAML content", async () => {
    const yaml = "key: value\nlist:\n  - one\n  - two";
    const result = await extractText(Buffer.from(yaml), "application/yaml");
    expect(result).toEqual({ text: yaml, truncated: false });
  });

  test("large text file is truncated with notice", async () => {
    const maxSize = 200;
    const largeText = "x".repeat(300);
    const result = await extractText(Buffer.from(largeText), "text/plain", maxSize);
    expect(result).not.toBeNull();
    expect(result!.truncated).toBe(true);
    expect(result!.text).toContain("[... truncated at 0 KB");
    expect(result!.text).toContain("use files__read for full content]");
    // The truncated text before the notice should be at most maxSize bytes
    const beforeNotice = result!.text.split("\n[... truncated")[0];
    expect(Buffer.byteLength(beforeNotice, "utf-8")).toBeLessThanOrEqual(maxSize);
  });

  test("custom truncation notice replaces files__read hint", async () => {
    const result = await extractText(Buffer.from("x".repeat(300)), "text/plain", 200, {
      truncatedSuffix: (kb) => `\n[... truncated at ${kb} KB]`,
    });

    expect(result).not.toBeNull();
    expect(result!.truncated).toBe(true);
    expect(result!.text).toContain("[... truncated at 0 KB]");
    expect(result!.text).not.toContain("files__read");
  });

  test("default maxSize truncates at 200KB", async () => {
    const size = 204_800 + 1000;
    const largeText = "a".repeat(size);
    const result = await extractText(Buffer.from(largeText), "text/plain");
    expect(result).not.toBeNull();
    expect(result!.truncated).toBe(true);
    expect(result!.text).toContain("[... truncated at 200 KB");
  });

  test("image/png returns null", async () => {
    const result = await extractText(Buffer.from([0x89, 0x50, 0x4e, 0x47]), "image/png");
    expect(result).toBeNull();
  });

  test("image/jpeg returns null", async () => {
    const result = await extractText(Buffer.from([0xff, 0xd8, 0xff]), "image/jpeg");
    expect(result).toBeNull();
  });

  test("application/x-executable returns null", async () => {
    const result = await extractText(
      Buffer.from([0x7f, 0x45, 0x4c, 0x46]),
      "application/x-executable",
    );
    expect(result).toBeNull();
  });

  test("unknown MIME type returns null", async () => {
    const result = await extractText(Buffer.from("data"), "application/octet-stream");
    expect(result).toBeNull();
  });

  test("any text/* subtype is decoded as UTF-8", async () => {
    // A .typ recovered to a text type extracts its source like any text file.
    const src = "#set page(width: 10cm)\n= Heading";
    const result = await extractText(Buffer.from(src), "text/x-typst");
    expect(result).toEqual({ text: src, truncated: false });
  });

  test("corrupted PDF returns null without throwing", async () => {
    const result = await extractText(Buffer.from("not a real pdf"), "application/pdf");
    expect(result).toBeNull();
  });

  test("corrupted DOCX returns null without throwing", async () => {
    const result = await extractText(
      Buffer.from("not a real docx"),
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    );
    expect(result).toBeNull();
  });

  test("corrupted XLSX returns null without throwing", async () => {
    const result = await extractText(Buffer.from("not a real xlsx"), XLSX_MIME);
    expect(result).toBeNull();
  });

  // A PK-signature buffer that is not a readable workbook gets past the magic
  // byte guard and into the parser, so this is the case that proves the parser
  // itself is caught rather than throwing into the file-ingest path.
  test("XLSX with valid zip signature but unreadable body returns null", async () => {
    const result = await extractText(Buffer.from("PK still not a workbook"), XLSX_MIME);
    expect(result).toBeNull();
  });

  // One round-trip over the whole grid. Asserted as a single string because the
  // "Multi" row holds a cell with an embedded newline — a line-split assertion
  // would tear that record in two and encode the wrong shape.
  //
  // Cell rendering belongs to the parser, which applies each cell's stored
  // number format, so this is not pinning hand-written logic: it is one check
  // that a real workbook survives the path intact, formats and all.
  test("XLSX extracts the first sheet as CSV", async () => {
    const result = await extractText(spreadsheetFixture(), XLSX_MIME);
    expect(result).not.toBeNull();
    expect(result?.truncated).toBe(false);
    expect(result?.text).toBe(
      [
        "Region,Units,Note,Opened,Checked,Shift,Active,Ratio",
        'West,12,"red, small",1/15/26,1/15/26 14:30,14:30,TRUE,50.0%',
        'East,7,"has ""quotes""",6/1/26,6/1/26 9:05,9:05,FALSE,#N/A',
        "Ünicode ✓,0,,12/31/25,,,TRUE,",
        'Multi,3.5,"line\nbreak",7/4/26,,,FALSE,',
        "Padded,1,  padded  ,,,,TRUE,",
      ].join("\n"),
    );
  });

  test("XLSX respects maxSize and marks the result truncated", async () => {
    const result = await extractText(spreadsheetFixture(), XLSX_MIME, 20);
    expect(result?.truncated).toBe(true);
    expect(result?.text.startsWith("Region,Units")).toBe(true);
  });

  test("empty buffer for text type returns empty string", async () => {
    const result = await extractText(Buffer.from(""), "text/plain");
    expect(result).toEqual({ text: "", truncated: false });
  });
});

/** Time and resident-memory growth of one extraction. */
async function measured<T>(
  run: () => Promise<T>,
): Promise<{ result: T; ms: number; rssMb: number }> {
  Bun.gc(true);
  const rss0 = process.memoryUsage().rss;
  const t0 = performance.now();
  const result = await run();
  const ms = performance.now() - t0;
  return { result, ms, rssMb: (process.memoryUsage().rss - rss0) / 1048576 };
}

/**
 * The text every page joined the way unpdf's whole-document `extractText`
 * returns it, then cut at `maxSize`: what extraction produced before it read
 * page by page, and what PDF sidecars already on disk hold.
 */
async function wholeDocumentPdfText(data: Buffer, maxSize: number): Promise<string> {
  const all = await unpdfExtractText(new Uint8Array(data));
  const text =
    all.totalPages > 1
      ? all.text.map((page, i) => `--- Page ${i + 1} ---\n${page}`).join("\n\n")
      : (all.text[0] ?? "");
  if (Buffer.byteLength(text, "utf-8") <= maxSize) return text;
  return `${Buffer.from(text, "utf-8").subarray(0, maxSize).toString("utf-8")}\n[... truncated at ${Math.round(maxSize / 1024)} KB]`;
}

/**
 * Whether the precheck refused `run`'s file, as opposed to a parser failing on
 * it after inflating it.
 */
async function refusedBeforeParsing<T>(run: () => Promise<T>): Promise<boolean> {
  const info = spyOn(log, "info");
  try {
    await run();
    return info.mock.calls.some(([msg]) => String(msg).includes("not extracted"));
  } finally {
    info.mockRestore();
  }
}

const REHYDRATE_SUFFIX = { truncatedSuffix: (kb: number) => `\n[... truncated at ${kb} KB]` };

describe("extractText bounds the work by the text it keeps", () => {
  // Each bomb is a few hundred KB on the wire and declares tens of MB of XML;
  // parsing one in full took seconds and gigabytes.
  test("a 1M-row XLSX bomb is refused before parsing", async () => {
    const bomb = xlsxWithRows(1_000_000);
    const { result, rssMb } = await measured(() => extractText(bomb, XLSX_MIME));
    expect(result).toBeNull();
    expect(rssMb).toBeLessThan(50);
    expect(await refusedBeforeParsing(() => extractText(bomb, XLSX_MIME))).toBe(true);
  });

  test("a 1M-paragraph DOCX bomb is refused before parsing", async () => {
    const bomb = docxWithParagraphs(1_000_000);
    const { result, rssMb } = await measured(() => extractText(bomb, DOCX_MIME));
    expect(result).toBeNull();
    expect(rssMb).toBeLessThan(50);
    expect(await refusedBeforeParsing(() => extractText(bomb, DOCX_MIME))).toBe(true);
  });

  // A file that understates its sizes passes the declared sums, and is refused
  // when an entry inflates past its declared size, before any parser reads it.
  // Understating only the large part leaves the small parts parseable.
  for (const where of ["everywhere", "central"] as const) {
    for (const entry of [undefined, "large part"] as const) {
      const which = entry ? `${where}, large part only` : where;
      test(`an XLSX bomb that understates its sizes (${which}) is refused`, async () => {
        const bomb = xlsxWithRows(1_000_000, {
          understate: { size: 1000, where, entry: entry && "xl/worksheets/sheet1.xml" },
        });
        const { result, rssMb } = await measured(() => extractText(bomb, XLSX_MIME));
        expect(result).toBeNull();
        expect(rssMb).toBeLessThan(50);
        expect(await refusedBeforeParsing(() => extractText(bomb, XLSX_MIME))).toBe(true);
      });

      test(`a DOCX bomb that understates its sizes (${which}) is refused`, async () => {
        const bomb = docxWithParagraphs(1_000_000, {
          understate: { size: 1000, where, entry: entry && "word/document.xml" },
        });
        const { result, rssMb } = await measured(() => extractText(bomb, DOCX_MIME));
        expect(result).toBeNull();
        expect(rssMb).toBeLessThan(50);
        expect(await refusedBeforeParsing(() => extractText(bomb, DOCX_MIME))).toBe(true);
      });
    }
  }

  // SheetJS sizes an entry's output buffer from the local header.
  test("a local header declaring more than the directory is refused before parsing", async () => {
    const data = xlsxWithRows(1);
    data.writeUInt32LE(128 * 1024 * 1024, 22);
    const alloc = spyOn(Buffer, "allocUnsafe");
    try {
      expect(await refusedBeforeParsing(() => extractText(data, XLSX_MIME, 20))).toBe(true);
      expect(alloc.mock.calls.every(([size]) => size < 1024 * 1024)).toBe(true);
    } finally {
      alloc.mockRestore();
    }
  });

  // A ZIP64 extra field replaces the header's sizes for a parser that reads it.
  // An unrelated record (an extended timestamp) comes first, so finding the
  // ZIP64 record needs the traversal; the same field without it extracts.
  const timestamp = Buffer.from([0x55, 0x54, 5, 0, 1, 0, 0, 0, 0]);
  const zip64 = Buffer.alloc(12);
  zip64.writeUInt16LE(0x0001, 0);
  zip64.writeUInt16LE(8, 2);
  zip64.writeBigUInt64LE(128n * 1024n * 1024n, 4);
  for (const where of ["local", "central"] as const) {
    test(`a ZIP64 extra field in the ${where} header is refused before parsing`, async () => {
      const plain = xlsxWithRows(1, { extraField: { field: timestamp, where } });
      expect((await extractText(plain, XLSX_MIME))?.text).toContain("aaaa");
      const data = xlsxWithRows(1, {
        extraField: { field: Buffer.concat([timestamp, zip64]), where },
      });
      expect(await refusedBeforeParsing(() => extractText(data, XLSX_MIME))).toBe(true);
    });
  }

  test("a zip whose end record miscounts its entries is refused", async () => {
    expect(
      await extractText(docxWithParagraphs(6_000, { entryCount: 0 }), DOCX_MIME, 10_000),
    ).toBeNull();
    expect(await extractText(docxWithParagraphs(10, { entryCount: 2 }), DOCX_MIME)).toBeNull();
  });

  // The budget follows maxSize: at 10,000 bytes of text the XML budget is
  // 256 KiB + 128 x 10,000 (XLSX, ~17,500 rows of 88 bytes) and
  // 256 KiB + 16 x 10,000 (DOCX, ~5,780 paragraphs of 73 bytes).
  test("an XLSX just under the budget still extracts, and just over it is refused", async () => {
    const under = await extractText(xlsxWithRows(10_000), XLSX_MIME, 10_000);
    expect(under?.truncated).toBe(true);
    expect(under?.text.startsWith("aaaa")).toBe(true);
    expect(await extractText(xlsxWithRows(19_000), XLSX_MIME, 10_000)).toBeNull();
  });

  test("a DOCX just under the budget still extracts, and just over it is refused", async () => {
    const under = await extractText(docxWithParagraphs(5_500), DOCX_MIME, 10_000);
    expect(under?.truncated).toBe(true);
    expect(under?.text.startsWith("aaaa")).toBe(true);
    expect(await extractText(docxWithParagraphs(6_000), DOCX_MIME, 10_000)).toBeNull();
  });

  // mammoth inlines each referenced image, so media counts toward what may be inflated.
  test("a DOCX declaring more than 64 MiB in all is refused", async () => {
    const media = { "word/media/image1.png": Buffer.alloc(65 * 1024 * 1024) };
    const result = await extractText(docxWithParagraphs(10, { extra: media }), DOCX_MIME);
    expect(result).toBeNull();
  });

  test("XLSX output is the whole sheet's output, truncated", async () => {
    // 3,000 rows of 40 characters pass a 2,000-byte cap long before the last row.
    const result = await extractText(xlsxWithRows(3_000), XLSX_MIME, 2_000);
    const full = `${"a".repeat(40)}\n`.repeat(3_000).slice(0, -1);
    expect(result?.text).toBe(
      `${full.slice(0, 2_000)}\n[... truncated at 2 KB — use files__read for full content]`,
    );
  });

  test("a sheet whose data starts far down extracts whole within a small maxSize", async () => {
    const sheet: XLSX.WorkSheet = { A100: { t: "s", v: "hello" }, "!ref": "A100:A100" };
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, sheet, "S");
    const data = XLSX.write(workbook, { type: "buffer", bookType: "xlsx" }) as Buffer;
    expect(XLSX.utils.sheet_to_csv(sheet)).toBe("hello");
    expect(await extractText(data, XLSX_MIME, 20)).toEqual({ text: "hello", truncated: false });
  });

  test("single-page and multi-page PDFs extract exactly as the whole-document read did", async () => {
    for (const pdf of [pdfWithPages(1), pdfWithPages(3), pdfWithPages(40)]) {
      const result = await extractText(pdf, "application/pdf", 204_800, REHYDRATE_SUFFIX);
      expect(result?.text).toBe(await wholeDocumentPdfText(pdf, 204_800));
      expect(result?.truncated).toBe(false);
    }
  });

  test("a PDF stops at the page where its text passes maxSize, with the same output", async () => {
    const pdf = pdfWithPages(2_000);
    const { result, ms } = await measured(() =>
      extractText(pdf, "application/pdf", 1_000, REHYDRATE_SUFFIX),
    );
    expect(ms).toBeLessThan(1000);
    expect(result?.truncated).toBe(true);
    expect(result?.text).toBe(await wholeDocumentPdfText(pdf, 1_000));
  });

  test("a PDF with little text stops at the page ceiling and says so", async () => {
    const result = await extractText(pdfWithPages(2_100, ""), "application/pdf");
    expect(result?.truncated).toBe(true);
    expect(result?.text.endsWith("\n[... text of the first 2000 of 2100 pages]")).toBe(true);
  });

  test("one extraction runs at a time; plain text does not wait", async () => {
    const finished: string[] = [];
    const pdf = extractText(pdfWithPages(1_000), "application/pdf").then(() => {
      finished.push("pdf");
    });
    const xlsx = extractText(xlsxWithRows(1), XLSX_MIME).then(() => {
      finished.push("xlsx");
    });
    const text = extractText(Buffer.from("hi"), "text/plain").then(() => {
      finished.push("text");
    });
    await Promise.all([pdf, xlsx, text]);
    // The XLSX parse is synchronous and tiny: run alongside, it would finish
    // before the 1,000-page PDF.
    expect(finished).toEqual(["text", "pdf", "xlsx"]);
  });
});
